class MultiFrameExpandContainer(EmbeddingContainer):
    """
    A MultiFrameExpandContainer is a special kind of loop container. It is considered to be
    parallellizable and does not strictly has to be a loop.
    """

    DEFAULT_LOCAL_VARIABLE_CLASS = LibRoutineLocalVariable
    SORT_CLASS = 0

    def __init__(
        self,
        *,
        context,
        local_variable_class=None,
        local_variable_capture=None,
        **buildargs,
    ):
        super().__init__(context=context, **buildargs)
        self._multiframe_variable = None
        self._max_value = None
        self._min_value = None
        self._local_variable_class = local_variable_class
        self._local_variable_capture = local_variable_capture

    def __lt__(self, other):
        """control the sorting order"""
        return self._lessthan(other)

    def _lessthan(self, other):
        return type(self).SORT_CLASS < type(other).SORT_CLASS

    def assign_multiframe_variable(
        self, variable, name="loc", local_variable_class=None
    ):
        """set the loop variable. This activates the loop"""
        self._multiframe_variable = variable
        self._max_value = variable.max_value
        self._min_value = variable.min_value
        if local_variable_class is None:
            local_variable_class = self._local_variable_class
        if local_variable_class is None:
            local_variable_class = type(self).DEFAULT_LOCAL_VARIABLE_CLASS
        self._multiframe_variable.create_local_representative(
            context=self.context,
            name=name,
            dtype="i32",
            size=None,
            local_variable_class=local_variable_class,
        )
        return self

    def generate_head_containers(self):
        if self._multiframe_variable is not None:
            yield from self.comment_from_text(
                f"BEGIN REPEAT {self._multiframe_variable.expr()} FROM {self._min_value} TO {self._max_value - 1}"
            )

    def generate_foot_containers(self):
        if self._multiframe_variable is not None:
            yield from self.comment_from_text(
                f"END REPEAT {self._multiframe_variable.expr()}"
            )


class ConditionalCaseContainer(EmbeddingContainer):
    """One branch of a generic conditional container."""

    INDENT_BODY = True

    def __init__(self, keyword, condition=None, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._keyword = keyword
        self._condition = condition

    def generate_head_containers(self):
        if self._keyword == "ELSE":
            yield from self.comment_from_text("ELSE")
            return
        yield from self.comment_from_text(
            f"{self._keyword} {self._condition}"
        )


class ConditionalContainer(EmbeddingContainer):
    """
    Generic conditional container made from one or more conditional branches.

    The generic representation deliberately stays textual and backend-neutral:
    concrete backends can override or replace it with language-specific
    conditionals later if needed.
    """

    def __init__(self, *, context, **params):
        """
        Initialize an empty generic conditional container.

        :param context: Parent build context.
        :param params: Additional container parameters.
        """
        super().__init__(context=context, **params)
        self._cases: list[ConditionalCaseContainer] = []
        self._else_case: ConditionalCaseContainer | None = None

    def add_case(self, condition, content=None):
        """
        Add a conditional branch.

        :param condition: Condition descriptor or textual condition.
        :param content: Optional container to append to the new branch.
        :returns: The branch container that receives appended content.
        """
        keyword = "IF" if not self._cases else "ELIF"
        case = ConditionalCaseContainer(
            keyword,
            condition,
            context=self.context,
        )
        self._cases.append(case)
        self.append_body(case)
        if content is not None:
            case.append(content)
        return case

    def set_else(self, content=None):
        """
        Add or replace the unconditional fallback branch.

        :param content: Optional container to append to the else branch.
        :returns: The else branch container.
        """
        if self._else_case is None:
            self._else_case = ConditionalCaseContainer(
                "ELSE",
                context=self.context,
            )
            self.append_body(self._else_case)
        if content is not None:
            self._else_case.append(content)
        return self._else_case

    def generate_foot_containers(self):
        """Close the generic conditional block once at least one case exists."""
        if self._cases:
            yield from self.comment_from_text("END IF")


class CaptureContainer(CodeContainer):
    """
    Generalization of Definition and Initialization Container, important for class
    hierarchy.
    """

    def __init__(self, *, context, **buildargs) -> None:
        self._filter_func_customs: List[Tuple(Callable, Callable, bool)] = []
        self._filter_func_types: List[Tuple(type, Callable, bool)] = []
        self._captured: List[LibRoutineVariable] = []

        super().__init__(context=context, **buildargs)
        # new namespace node in capture container
        self.context.new_namespace_node()

    def manage_captured(self, **kwargs):
        """
        Prepare captured variables before rendering.

        Subclasses override this to convert captured variables into generated
        child containers or namespace state.
        """

    def build(self, **kwargs):
        """Build the capture container after managing captured variables."""
        self.manage_captured(**kwargs)
        return super().build(**kwargs)

    def add_capture_trigger(
        self,
        capture: Type | Callable,
        callback: Callable | None = None,
        forward: bool = False,
    ) -> None:
        """
        Register a capture filter for incoming requirements.

        :param capture: Variable subclass or predicate function.
        :param callback: Optional callback executed when capture succeeds.
        :param forward: If ``True``, forward the requirement upward after
            capturing it.
        """
        if isinstance(capture, str):
            raise TypeError("not supported anymore")
            # self._filter_func_vtypes.append((capture, callback, forward))
            # return
        if isinstance(capture, type):
            if issubclass(capture, LibRoutineVariable):
                self._filter_func_types.append((capture, callback, forward))
                return
        if callable(capture):
            self._filter_func_customs.append((capture, callback, forward))
            return
        raise ValueError(
            f"Invalid filter arg {capture}. Must be str|callable."
        )

    @property
    def captured(self):
        """get the captured libvariables"""
        yield from self._captured

    def __contains__(self, variable):
        return any(var == variable for var in self._captured)

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        debug(f"capture check at {self} of requirement {requirement}")
        # if requirement.vtype in self._filter_func_vtypes:
        #     callback = self._filter_func_vtypes[requirement.vtype]
        #     if callback is not None:
        #         callback(requirement)
        #     debug(f"vtype in {self._filter_func_vtypes}")
        #     return True
        for func, callback, forward in self._filter_func_customs:
            if func(requirement):
                if callback is not None:
                    callback(requirement)
                debug(f"function approved")
                if forward:
                    super().requires(requirement)
                return True
        for reference_class, callback, forward in self._filter_func_types:
            if isinstance(requirement.plain, reference_class):
                if callback is not None:
                    callback(requirement)
                debug(f"is subtype of {reference_class}")
                if forward:
                    debug("forward requirement")
                    super(CaptureContainer, self).requires(requirement)
                return True
        debug("capture check was failed")
        return False

    def provides(self, variable):
        """
        Register a captured variable as provided by this container.

        The variable is stored locally and inserted into the active namespace so
        descendant contexts can resolve it.
        """
        if variable not in self._captured:
            self._captured.append(variable)
        self.namespace.add(variable)

    def requires(self, variable):
        """
        Intercept or forward a variable dependency.

        :param variable: Required variable.
        """
        if isinstance(variable, Numeric):
            return None
        if isinstance(variable, ValueAt):
            return self.requires(variable.plain)
        if self.capture_check(variable):
            for dep in variable.dependencies:
                self.requires(dep)
            self.provides(variable)
            return None
        return super().requires(variable)

    def reset_captured(self) -> None:
        """reset the provided requirements"""
        self._captured = []
        return super().reset_captured()


class DefinitionContainer(CaptureContainer, PreambleContainer):
    """
    A code container that defines stuff and prevents them from getting passed
    on during requirement iterator. Supports a filtering function that decides
    on which type of requirements are implemented here or passed on.
    """

    INDENT_BODY = False
    INDENT_PRMB = False

    def generate_prmb_containers(self, **kwargs):
        for variable in self.captured:
            yield DefinitionLines(variable, context=self.context, **kwargs)


class HiddenLayersContainer(CodeContainer):
    """
    Provide Hidden Layer Functionality

    The structure of containers can be different than the ideal path of requests
    arising from their contents.
    Therefore, hidden layers can be introduced that are not simply plain containers
    inside another container, these are individual units that are placed in the
    context tree.
    Hidden layers will be placed before the actual container is placed, i.e. further
    outside.
    Hidden layers init will prepare all hidden layers and
    """

    def __init__(self, *args, context, **buildargs):
        self._hidden_layers = []
        self._context_main_ptr = context
        self._prep_mode = True
        self._context_main_ptr = self.prepare_hidden_layers(**buildargs)
        self._prep_mode = False
        super().__init__(*args, context=self._context_main_ptr, **buildargs)

    def add_hidden_layer(self, layer_class, **buildargs):
        """add a layer to the hidden list"""
        # build the layer
        if not self._prep_mode:
            raise RuntimeError(
                "adding layers should only be done within the prepare_hidden_layers method"
            )
        layer = layer_class(context=self._context_main_ptr, **buildargs)
        # add to list
        self._hidden_layers.append(layer)
        # update the pointer
        self._context_main_ptr = layer.context
        return layer

    def prepare_hidden_layers(self, **_):
        """create layers before self"""
        return self._context_main_ptr

    def build(self, **kwargs):
        for layer in self._hidden_layers[::-1]:
            layer.build(**kwargs)
        return super().build(**kwargs)

    def get_codelines_body(self, indent: int = 0, **kwargs):
        # for layer in self._hidden_layers:
        #     yield from layer.get_codelines(indent=indent, **kwargs)
        yield from super().get_codelines_body(indent=indent, **kwargs)


class RoutineContainer(
    NamedContainer,
    HiddenLayersContainer,
    EmbeddingContainer,
    PreambleContainer,
    ConfiguredContainer,
):
    """
    How a routine is defined, especially handles the section where the arguments
    are passed and opening/enclosing statements.
    """

    # should provide a string how the routine is called
    # should provide a general signature database for imports
    # libraries can provide that and when a library is imported, the
    # signatures are provided

    INDENT_BODY = True

    INPUT_VARIABLE_CLASS = LibRoutineInputVariable

    def __init__(
        self,
        name,
        *,
        context,
        **buildargs,
    ):
        unique_name = UniqueString(name, namespace=context.namespace)

        self._ios_layer = None
        self._loc_layer = None
        self._rep_layer = None
        self._arg_layer = None

        # self._kern_args = None
        self._call_args = None

        super().__init__(name=unique_name.name, context=context, **buildargs)

        self._rep_layer = self.create_attached_loop_capture(**buildargs)
        self.append_body(self._rep_layer)
        self.set_attachment_point(self._rep_layer)

    def configure_container(self, **_):
        # what that ends up here is considered in-out
        self._ios_layer.add_capture_trigger(LibRoutineInputVariable)
        self._ios_layer.add_capture_trigger(LibRoutineOutputVariable)
        self._ios_layer.add_capture_trigger(LibRoutineInOutVariable)

        # remember local variables for header defs
        self._loc_layer.add_capture_trigger(LibRoutineLocalVariable)

        # remember everything at this point
        self._arg_layer.add_capture_trigger(LibRoutineInputVariable)
        self._arg_layer.add_capture_trigger(LibRoutineOutputVariable)
        self._arg_layer.add_capture_trigger(LibRoutineInOutVariable)
        self._arg_layer.add_capture_trigger(LibRoutineMultiFrame)

        # treat special mfs. What passes this layer is traditional call arg
        # self._ker_layer.add_capture_trigger(LibRoutineMultiFrame)

        return super().configure_container()

    def create_attached_loop_capture(self, **buildargs):
        """create the global loop capture at the routine's container body"""
        return LoopCaptureContainer(context=self.context, **buildargs)

    def prepare_hidden_layers(self, **buildargs):
        self._ios_layer = self.add_hidden_layer(CaptureContainer, **buildargs)
        self._loc_layer = self.add_hidden_layer(CaptureContainer, **buildargs)
        self._arg_layer = self.add_hidden_layer(CaptureContainer, **buildargs)
        # self._ker_layer = self.add_hidden_layer(CaptureContainer, **buildargs)
        return super().prepare_hidden_layers()

    def get_inout_variables(self, **_):
        """list the variables that show up in the argument list"""
        for variable in sorted(self._ios_layer.captured):
            yield variable

    def get_call_variables(self, **_):
        """list the variables that show up in the argument list"""
        for variable in sorted(self._call_args):
            yield variable

    def get_argument_variables(self, **_):
        """list the variables that show up in the argument list"""
        for variable in sorted(self._arg_layer.captured):
            yield variable

    def get_local_variables(self, **_):
        """list the inner variables"""
        for variable in self._loc_layer.captured:
            yield variable

    def get_kernel_variables(self):
        """get the kernel multiframe variables"""
        yield from ()

    # def treat_kernel_variable(self, variable):
    #     """Treat a kernel variable"""
    #     # TODO
    #     # CUDA-like input representatives need to have a version that
    #     # introduces them as locals and assigns tid, gid, ... rather than
    #     # an argument that goes to input.
    #     # Additionally, these kind of variables need to raise a call info
    #     # that is caught somewhere further up.
    #     # Ideally, the LoopCapture creates the proper multiframe that creates
    #     # the right representative automatically and an extra capture layer
    #     # extracts them
    #     return variable

    def prepare_call_arguments(self):
        """
        prepare the arguments for call, do all the work to resolve MFs that are not
        resolved yet
        """
        self._call_args = []
        num = 0
        for variable in self._arg_layer.captured:
            if isinstance(variable, LibRoutineMultiFrame):
                name = f"krnl_{num:02d}"
                num += 1
                loc = variable.create_input_representative(
                    context=self.context,
                    dtype="i32",
                    size=None,
                    name=name,
                    input_variable_class=type(self).INPUT_VARIABLE_CLASS,
                    autorequire=False,
                )
                self._ios_layer.requires(loc)
            else:
                self._ios_layer.requires(variable)
            self._call_args.append(variable)

    # def prepare_kernel_arguments(self):
    #     """prepare the multiframe variables among the arguments"""
    #     for var in self._ker_layer.captured:
    #         self._ker_layer.parent.requires(var)

    def build(self, **kwargs):
        # first handle kernel args (requested during creation)
        # then build the rest, knowing the local representation
        self.prepare_call_arguments()
        return super().build(**kwargs)

    def generate_prmb_containers(self, **kwargs):
        """
        Generate routine-level definition sections for arguments and locals.
        """
        yield from self.comment_from_text("IN/OUT/INOUT")
        for variable in self.get_inout_variables():
            yield DefinitionLines(variable, context=self.context, **kwargs)
        yield from self.codelines_from_text("")
        yield from self.comment_from_text("LOCAL")
        for variable in self.get_local_variables():
            yield DefinitionLines(variable, context=self.context, **kwargs)
        yield from self.codelines_from_text("")

    def generate_head_containers(self, **_):
        call_args = (
            variable.as_argument()
            for variable in self.get_argument_variables()
        )
        yield from self.comment_from_text(
            f"BEGIN FUNCTION {self.name} ({', '.join(call_args)})"
        )

    def generate_foot_containers(self, **_):
        yield from self.comment_from_text(f"END FUNCTION {self.name}")


class ImportContainer(CodeLine):
    """Import a routine or routine-like object"""

    def __init__(self, library, routines, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._library = library
        self._routines = routines

    def construct_code_lines(self, **_):
        """create the codelines required for the import"""
        if type(self) is ImportContainer:
            for routine in self.routines:
                yield from self.comment_codelines_from_text(
                    f"IMPORT {routine.name} FROM {self.library.libname}"
                )
            return
        for routine in self.routines:
            yield f":IMPORT: {routine.name} from {self.library.libname}"

    @property
    def library(self):
        """read-only access to library"""
        return self._library

    @property
    def routines(self):
        """read-only access to routines"""
        yield from self._routines


class RoutineCallContainer(CodeLine):
    """Call a routine or routine-like object"""

    def __init__(self, imported_routine, *, context, call_requests=None, **buildargs):
        super().__init__(context=context, **buildargs)
        self._imp_routine = imported_routine
        # assert isinstance(imported_routine.imported, LibRoutine)
        self._call_args = []
        if call_requests is None:
            call_requests = tuple(
                variable.assignment
                if variable.assignment is not None
                else variable
                for variable in imported_routine.imported.get_arguments()
            )
        for _variable, request in zip(
            imported_routine.imported.get_arguments(),
            call_requests,
            strict=True,
        ):
            self._call_args.append(
                self.resolve_call_request(
                    request,
                    context=context,
                )
            )
        self.requires(self._imp_routine)

    def resolve_call_request(self, request, *, context):
        """Resolve one normalized builder request in the local namespace."""
        if isinstance(request, LibRoutineMultiFrame):
            local = request.recreate(namespace=context.namespace)
            self.requires(local)
            return local
        if isinstance(request, Numeric):
            return request
        if isinstance(request, tuple) and len(request) == 2:
            source, key = request
            local = self.request_assigned(source, key, autorequire=True)
            if local is None:
                raise KeyError(
                    f"cannot resolve call assignment for {source}[{key}]"
                )
            return local
        raise TypeError(f"unsupported call request: {request}")

    def construct_code_lines(self, **_):
        # call name depends on import section
        if type(self) is RoutineCallContainer:
            yield from self.comment_codelines_from_text(self.get_call_string())
            return
        yield self.get_call_string()

    def get_call_string(self):
        """generate the call string"""
        return f"CALL {self.get_call_name()}({', '.join(self.get_args_list())})"

    def get_args_list(self):
        """get the args list"""
        call_args = []
        for call_arg in self._call_args:
            if isinstance(call_arg, LibRoutineMultiFrame):
                call_arg = call_arg.local
            call_args.append(call_arg)
        rendered = []
        for call_arg in call_args:
            if isinstance(call_arg, Numeric):
                rendered.append(call_arg.expr())
            else:
                rendered.append(call_arg.as_argument())
        return rendered

    # generate the call using info from the Imported variable
    def get_call_name(self):
        return self._imp_routine.call_name


class ImportSectionContainer(
    CaptureContainer, EmbeddingContainer, ConfiguredContainer
):
    """Capture all imports"""

    DEFAULT_IMPORT_LINE_CLASS = ImportContainer

    def __init__(self, *, context, import_line_class=None, **buildargs):
        super().__init__(context=context, **buildargs)
        if import_line_class is None:
            import_line_class = type(self).DEFAULT_IMPORT_LINE_CLASS
        self._import_line_class = import_line_class
        self._grouped_imports = []

    def configure_container(self, **_):
        """setup the defaults"""
        self.add_capture_trigger(ExternalImport)
        return super().configure_container()

    def list_imports(self):
        """list the imports in the format (library, [routine1, routine2, ...])"""
        yield from self._grouped_imports

    def manage_captured(self, **kwargs):
        # called in build. Preselect and check the imports
        captured_imports = []
        self._grouped_imports = []
        for to_be_imported in self._captured:
            # check for compatibility
            if not self.compatibility_check(to_be_imported):
                raise ValueError(
                    f"Library {to_be_imported.library} does not match current library"
                )
            captured_imports.append(to_be_imported)

        # add the import codelines to the body. tidy_imports does the grouping
        for library, importable in self.tidy_imports(captured_imports).items():
            content_selection = []
            for potential_importable in importable:
                if self.check_import_required(library, potential_importable):
                    content_selection.append(potential_importable)
                    potential_importable.set_call_name(
                        self.compose_call_name(potential_importable, library)
                    )
                else:
                    potential_importable.set_call_name(
                        self.compose_call_name(potential_importable, None)
                    )
            if content_selection:
                self._grouped_imports.append((library, content_selection))

    def check_import_required(self, library, routine):
        """filter the imports whether they are required or not"""
        if library == self.context.library:
            return False
        return True

    def generate_head_containers(self, **kwargs):
        for library, routines in self._grouped_imports:
            yield self._import_line_class(
                library, routines, context=self.context, **kwargs
            )

    def compose_call_name(self, importable, library):
        """compose the name of the call"""
        imported_name = importable.imported.name
        if library is None:
            return f"{imported_name}"
        return f"{library.libname}.{imported_name}"

    def tidy_imports(self, list_of_imports):
        """tidy the imports, i.e. handle groups, repeats, ..."""
        grouped = {}
        for this_import in list_of_imports:
            if this_import.library not in grouped:
                grouped[this_import.library] = set()
            grouped[this_import.library].add(this_import)
        return grouped

    def compatibility_check(self, _to_be_imported):
        """check if libroutine is compatible"""
        return True

    def reset(self, **kwargs):
        self._grouped_imports = []
        return super().reset(**kwargs)


class LoopCaptureContainer(
    HiddenLayersContainer,
    ConfiguredContainer,
    EmbeddingContainer,
    CaptureContainer,
):
    """A capture container that reacts on multi frame objects."""

    INDENT_BODY = False

    def __init__(self, *, context, **buildargs):
        self._outer_capture = None
        super().__init__(context=context, **buildargs)
        # to capture variables that are local inside the loop body
        self._outer_capture.add_capture_trigger(
            LibRoutineLocalVariable, forward=True
        )
        # Note: if this capture is inside, it does not automatically
        # capture the local variable created from the loops themselves

        self._loop_body = GroupContainer(context=self.context, **buildargs)
        self.set_attachment_point(self._loop_body)

        self._mfe_hook = self
        self._mfe_containers = []
        self._loop_counter = 0

        self._action_counter = 0

    def configure_container(self, **_):
        """setup the defaults"""
        self.add_capture_trigger(
            LibRoutineMultiFrame, callback=self.handle_new_mfe
        )
        return super().configure_container()

    def handle_new_mfe(self, variable):
        """callback to handle passing multiframe right away"""
        assert isinstance(variable, LibRoutineMultiFrame)
        if variable in self:
            return
        self._action_counter += 1

        new_container = self.context.request_resource_mfe_container(
            variable=variable,
            name=f"cntr_l{self.level}_n{self._loop_counter}_a{self._action_counter}",
            local_variable_capture=self._outer_capture,
            loop_capture=self,
        )
        if new_container is None:
            self._outer_capture.requires(variable)
        else:
            self._mfe_containers.append(new_container)
            self._loop_counter += 1

    def prepare_hidden_layers(self, **_):
        self._outer_capture = self.add_hidden_layer(CaptureContainer)
        return super().prepare_hidden_layers()

    def build(self, **kwargs):
        super().build(**kwargs)
        self._mfe_hook = None
        for container in self._mfe_containers:
            if self._mfe_hook is None:
                self.append_body(container)
            else:
                self._mfe_hook.append(container)
            self._mfe_hook = container
            self._mfe_hook.build_all()

        return self

    def build_all(self, **kwargs):
        self._loop_body.build_all(**kwargs)
        super().build_all(**kwargs)
        if self._mfe_hook is None:
            self.append_body(self._loop_body)
        else:
            self._mfe_hook.append(self._loop_body)
        return self

    def reset(self, **kwargs):
        self._mfe_containers = []
        self._loop_counter = 0
        return super().reset(**kwargs)


class LibraryContainer(
    NamedContainer,
    EmbeddingContainer,
    PreambleContainer,
    ConfiguredContainer,
):
    """
    A Library contains routines, constants and more.
    The Library Container provides generalized routines to add
    libroutines, imports, constants, ... that can be called
    """

    INDENT_BODY = True
    INDENT_PRMB = True

    def __init__(
        self, name, *, context, import_line_class=ImportContainer, **buildargs
    ):
        self._imp_layer = ImportSectionContainer(
            context=context, import_line_class=import_line_class
        )
        self._def_layer = DefinitionContainer(context=self._imp_layer.context)
        super().__init__(name, context=self._def_layer.context, **buildargs)
        self._context._library = self

    def configure_container(self, **_):
        """setup the defaults"""
        self._def_layer.add_capture_trigger(LibRoutineConstant)
        self._imp_layer.add_capture_trigger(ExternalImport)
        return super().configure_container()

    def build(self, **kwargs):
        """Build import and constant helper layers before the library body."""
        self._imp_layer.build(**kwargs)
        self._def_layer.build(**kwargs)
        return super().build(**kwargs)

    def generate_prmb_containers(self, **_):
        yield from self.comment_from_text("IMPORTS")
        yield self._imp_layer
        yield from self.codelines_from_text("")
        yield from self.comment_from_text("CONSTANTS")
        yield self._def_layer
        yield from self.codelines_from_text("")
        yield from self.comment_from_text("ROUTINES")
        yield from self.codelines_from_text("")

    def generate_clsg_containers(self, **_):
        yield from self.comment_from_text("END OF ROUTINES")

    def generate_head_containers(self, **_):
        """make the enclosings for this container"""
        yield from self.comment_from_text(f"BEGIN LIBRARY {self.name}")

    def generate_foot_containers(self, **_):
        yield from self.comment_from_text(f"END LIBRARY {self.name}")

    @property
    def captured_imports(self):
        """access the captured external routines"""
        yield from self._imp_layer.captured


class HookContainer(CodeLine):
    """
    A HookContainer is a dummy placeholder to be able to require variables and more
    without the need to place some lines there
    """

    def __init__(self, *, context, **buildargs):
        super().__init__(None, context=context, **buildargs)

    def construct_code_lines(self, **_):
        """construct the code line"""
        # this is a generator to include line breaks if necessary
        return
        yield


class IntCombineExpandContainer(MultiFrameExpandContainer):
    """Container recombining split integer-loop dimensions into one index."""

    INDENT_BODY = True
    SORT_CLASS = 100

    def __init__(
        self,
        first,
        second,
        *,
        local_variable_class=None,
        local_variable_capture=None,
        context,
        **buildargs,
    ):
        super().__init__(
            local_variable_class=local_variable_class,
            local_variable_capture=local_variable_capture,
            context=context,
            **buildargs,
        )
        self._first = first
        self._second = second

    def generate_head_containers(self, **_):
        # yield from self.codelines_from_text(
        #     f"! combine {self._variable.local}, {self._first.local} {self._second.local} {self._offset}"
        # )
        yield from self.comment_from_text(
            f"{self._multiframe_variable.local} = {self._second.local} * {self._first.max_value} + {self._first.local}"
            + (
                f" + {self._multiframe_variable.min_value}"
                if self._multiframe_variable.min_value
                else ""
            )
        )
        yield from self.comment_from_text(
            f"IF {self._multiframe_variable.local} < {self._multiframe_variable.max_value} THEN"
        )

    def generate_foot_containers(self, **_):
        yield from self.comment_from_text("END IF")
